    {
      "check_id": "CKV2_AZURE_16",
      "title": "Ensure that MySQL server enables customer-managed key for encryption",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The MySQL server does not use a customer-managed key for encryption, which provides better control over encryption keys."
    },
    {
      "check_id": "CKV_AZURE_28",
      "title": "Ensure 'Enforce SSL connection' is set to 'ENABLED' for MySQL Database Server",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The MySQL server does not explicitly enforce SSL connections, which could allow unencrypted connections."
    },
    {
      "check_id": "CKV_AZURE_54",
      "title": "Ensure MySQL is using the latest version of TLS encryption",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The MySQL server does not specify the minimum TLS version, which could result in weaker encryption being used."
    }
  ],
  "patched_code": "resource \"azurerm_mysql_server\" \"changeme_simple_mysql_server\" {\n  name                = \"changeme-simple-mysql-database-name\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mysql_server_resource_group.location\n  storage_mb          = \"5120\"\n  sku_name            = \"B_Gen5_1\"\n  version             = \"8.0\"\n  administrator_login = \"changemeadmin\"\n  administrator_login_password = \"ch4ng3m3-A@Â£$%^&\"\n\n  ssl_enforcement_enabled = true\n  infrastructure_encryption_enabled = true\n  minimal_tls_version = \"TLS1_2\"\n\n  identity {\n    type = \"SystemAssigned\"\n  }\n\n  private_endpoint_connection {\n    private_dns_zone_id = azurerm_private_dns_zone.example.id\n    subnet_id           = azurerm_subnet.example.id\n  }\n\n  key_vault_key_id = azurerm_key_vault_key.example.id\n}",
  "fix_summary": "Enabled infrastructure encryption, enforced the latest TLS version, added a private endpoint configuration, and specified a customer-managed key for encryption. These changes enhance data security and restrict public exposure."
